-- Migration 042: KPI 2026 H1 cycle - templates, lines, items and outcome bands
-- Loaded from the CSI KPI 2026 Guideline (lines, weights, targets), the v10
-- Calculator (rating bands) and the BIM forms (BIM rating bands). Structure only:
-- no staff names and no scores. Everything here is editable in the app.
-- Written as INSERT ... SELECT so a fresh database that has no ROLE rows yet
-- (roles come from seed/001) simply loads no templates instead of failing.

INSERT INTO KPI_CYCLE (CycleCode, Name, PeriodStart, PeriodEnd, Status, Config) VALUES (
  '2026-H1', 'KPI 2026 - H1 (Jan-Jun)', DATE '2026-01-01', DATE '2026-06-30', 'Draft',
  $q${"certificates": {"categories": [{"code": "General", "points": 1, "maxTotal": 5}, {"code": "Supporting", "points": 2, "maxTotal": 5}, {"code": "Core", "points": 5, "minCount": 1}], "scoreCap": 10}}$q$::jsonb);

INSERT INTO KPI_TEMPLATE (CycleId, RoleId, DisplayName, SortOrder)
SELECT c.id, r.id, v.dn, v.so
FROM (VALUES
  ('SVP', $q$Senior Vice President$q$, 1),
  ('HOD', $q$Head of Department (CSI)$q$, 2),
  ('SM', $q$Solution Manager / Deputy HOD$q$, 3),
  ('TL', $q$Team Lead$q$, 4),
  ('TM', $q$Pre-Sales Executive / Solution Executive$q$, 5),
  ('BIM_TL', $q$BIM Team Lead (BIM Manager)$q$, 6),
  ('BIM_MOD', $q$BIM Modeler$q$, 7)
) AS v(rc, dn, so)
JOIN ROLE r ON r.rolecode = v.rc
CROSS JOIN KPI_CYCLE c WHERE c.cyclecode = '2026-H1';

