  ('TM', 7, $q$Compliance Response Quality$q$, $q$Assigned compliance response is accurate, complete, traceable, and supported with evidence / datasheet / clarification$q$, $q$100% assigned compliance completed$q$, $q$Staff must ensure compliance answers are clear, correct, and supported with evidence.$q$, 15.0::numeric, NULL, $q${"5": "100% assigned compliance completed, traceable and supported with evidence", "4": "90% – 99.99% complete with minor gaps", "3": "75% – 89.99% complete", "2": "50% – 74.99% complete", "1": "< 50% or major compliance gap"}$q$::jsonb),
  ('TM', 8, $q$Documentation & Knowledge Repository$q$, $q$Proposal files, BoM records, datasheets, compliance evidence, clarification response, and reusable notes maintained$q$, $q$100% updated$q$, $q$Staff must keep documents organized and reusable.$q$, 10.0::numeric, NULL, $q${"5": "100% proposal files, BoM records, datasheets and reusable notes updated", "4": "90% – 99.99% updated with minor delay", "3": "75% – 89.99% updated", "2": "50% – 74.99% updated", "1": "< 50% or no repository evidence"}$q$::jsonb),
  ('TM', 9, $q$Certification & Competency Development$q$, $q$Achieve relevant certification, product competency, solution writing capability, or approved learning milestone$q$, $q$Minimum 1 certification / competency milestone per year$q$, $q$Staff must improve technical skills and achieve planned competency.$q$, 10.0::numeric, NULL, $q${"5": "Certification or approved competency milestone achieved", "4": "Training completed / exam attempted with strong progress", "3": "Partial progress recorded", "2": "Limited progress recorded", "1": "No progress evidence"}$q$::jsonb),
  ('BIM_TL', 1, $q$BIM Delivery Management$q$, $q$BIM-related tender, proposal, modelling, drawing, visualization, coordination, or project support tasks are assigned, monitored, and delivered$q$, $q$>=95% within agreed SLA$q$, $q$BIM Team Lead ensures BIM tasks are planned, assigned, and completed on time.$q$, 25.0::numeric, $q$SLA Compliance %$q$, $q${"5": ">= 95% BIM tasks completed within agreed SLA", "4": "85% - 94.99% completed within agreed SLA", "3": "70% - 84.99% completed within agreed SLA", "2": "50% - 69.99% completed within agreed SLA", "1": "< 50% or repeated late delivery"}$q$::jsonb),
  ('BIM_TL', 2, $q$BIM Quality Control$q$, $q$BIM model, drawing, coordination file, visualization, and submission output reviewed with minimal major correction or rework$q$, $q$>=95% accepted quality$q$, $q$BIM Team Lead checks BIM output before it is submitted or used.$q$, 20.0::numeric, NULL, $q${"5": ">= 95% BIM output accepted with minimal major correction", "4": "85% - 94.99% accepted quality", "3": "70% - 84.99% accepted quality", "2": "50% - 69.99% accepted quality", "1": "< 50% or major repeated rework"}$q$::jsonb),
  ('BIM_TL', 3, $q$BIM Standards & Submission Compliance$q$, $q$BIM output complies with client requirement, LOD, naming convention, file structure, drawing standard, and submission format$q$, $q$100% major compliance$q$, $q$BIM Team Lead ensures BIM work follows the required standard.$q$, 15.0::numeric, NULL, $q${"5": "100% major BIM compliance achieved", "4": "90% - 99.99% compliant with minor gaps", "3": "75% - 89.99% compliant", "2": "50% - 74.99% compliant", "1": "< 50% or major non-compliance"}$q$::jsonb),
  ('BIM_TL', 4, $q$BIM Coordination & Resource Control$q$, $q$BIM task assignment, model review, issue log, clash input, progress tracking, and internal coordination maintained$q$, $q$100% active tracking$q$, $q$BIM Team Lead controls task assignment, progress, and BIM coordination.$q$, 10.0::numeric, NULL, $q${"5": "100% BIM task assignment, progress, issue log and coordination actively tracked", "4": "90% - 99.99% tracked with minor gaps", "3": "75% - 89.99% tracked", "2": "50% - 74.99% tracked", "1": "< 50% or no tracker evidence"}$q$::jsonb),
  ('BIM_TL', 5, $q$BIM Tender / Proposal Support$q$, $q$BIM input, visualization, drawing, model, or technical support contributes to proposal readiness, project delivery support, internal presentation, or client clarification$q$, $q$Contribution recorded for assigned BIM-related tasks$q$, $q$BIM Team Lead supports proposals or project work through BIM output.$q$, 10.0::numeric, NULL, $q${"5": "Strong support to proposal / project readiness", "4": "Clear contribution to BIM-related submission or clarification", "3": "Contribution recorded but limited impact", "2": "Minimal support recorded", "1": "No BIM support evidence"}$q$::jsonb),
  ('BIM_TL', 6, $q$Commission$q$, $q$Contribution to awarded / eligible commissionable projects based on company commission policy$q$, $q$Minimum 3x employee basic salary$q$, $q$BIM Team Lead contributes to awarded projects that qualify for commission.$q$, 5.0::numeric, NULL, $q${"5": ">= 3.00x basic salary achieved", "4": "2.00x - 2.99x basic salary achieved", "3": "1.00x - 1.99x basic salary achieved", "2": "0.50x - 0.99x basic salary achieved", "1": "< 0.50x or no commissionable contribution"}$q$::jsonb),
  ('BIM_TL', 7, $q$BIM Process Improvement & Reusable Assets$q$, $q$Reusable family / object, template, clash workflow, visualization approach, modelling efficiency, or BIM standard improvement introduced$q$, $q$Minimum 1 improvement per quarter$q$, $q$BIM Team Lead improves BIM workflow, templates, or reusable BIM assets.$q$, 10.0::numeric, NULL, $q${"5": ">= 4 documented BIM improvements / reusable assets per year", "4": "3 documented BIM improvements / reusable assets per year", "3": "2 documented BIM improvements / reusable assets per year", "2": "1 documented BIM improvement / reusable asset per year", "1": "No improvement evidence"}$q$::jsonb),
  ('BIM_TL', 8, $q$BIM Documentation & Version Governance$q$, $q$BIM records, model versions, drawing registers, review comments, and submission records maintained$q$, $q$100% documentation updated$q$, $q$BIM Team Lead ensures BIM records and versions are properly controlled.$q$, 3.0::numeric, NULL, $q${"5": "100% BIM records, model versions, drawing registers and submission records updated", "4": "90% - 99.99% updated with minor gaps", "3": "75% - 89.99% updated", "2": "50% - 74.99% updated", "1": "< 50% or poor version control evidence"}$q$::jsonb),
  ('BIM_TL', 9, $q$BIM Capability & Certification Development$q$, $q$BIM certification, modelling competency, knowledge sharing, and tool capability improvement achieved$q$, $q$Minimum 1 competency / certification milestone per year$q$, $q$BIM Team Lead develops BIM skill capability for self and team.$q$, 2.0::numeric, NULL, $q${"5": "Certification or approved BIM competency milestone achieved", "4": "Training completed / exam attempted with strong progress", "3": "Partial progress recorded", "2": "Limited progress recorded", "1": "No progress evidence Recommended Governance Note KPI rating shall be assessed using a 5-to-1 scale. Rating 5 represents full achievement or exceeding target, while Rating 1 represents non-achievement or insufficient evidence. Assessment shall be based on measurable records such as WO tracker, proposal register, tender outcome, BoM review record, compliance matrix, BIM register, OI register, commission record, certification tracker, meeting minutes, and management reporting evidence."}$q$::jsonb),
  ('BIM_MOD', 1, $q$BIM Modelling / Drawing Task Completion$q$, $q$Assigned BIM modelling, drawing, revision, visualization, or coordination task completed according to instruction$q$, $q$>=95% within agreed SLA$q$, $q$BIM Modeler must complete assigned model or drawing tasks on time.$q$, 30.0::numeric, $q$SLA Compliance %$q$, $q${"5": ">= 95% assigned BIM modelling / drawing tasks completed within SLA", "4": "85% - 94.99% completed within SLA", "3": "70% - 84.99% completed within SLA", "2": "50% - 69.99% completed within SLA", "1": "< 50% or repeated late delivery"}$q$::jsonb),
  ('BIM_MOD', 2, $q$Model / Drawing Quality & Accuracy$q$, $q$Model, drawing, revision, or visualization output accepted by BIM Team Lead with minimal major correction$q$, $q$>=95% accepted quality$q$, $q$BIM Modeler must produce accurate model or drawing output.$q$, 25.0::numeric, NULL, $q${"5": ">= 95% model / drawing output accepted with minimal major correction", "4": "85% - 94.99% accepted quality", "3": "70% - 84.99% accepted quality", "2": "50% - 69.99% accepted quality", "1": "< 50% or major repeated rework"}$q$::jsonb),
  ('BIM_MOD', 3, $q$BIM Standards Compliance$q$, $q$Output follows required LOD, naming convention, drawing standard, file structure, and submission format$q$, $q$100% major compliance$q$, $q$BIM Modeler must follow BIM standards and file requirements.$q$, 15.0::numeric, NULL, $q${"5": "100% BIM standards compliance achieved", "4": "90% - 99.99% compliant with minor gaps", "3": "75% - 89.99% compliant", "2": "50% - 74.99% compliant", "1": "< 50% or major non-compliance"}$q$::jsonb),
  ('BIM_MOD', 4, $q$Version Control & Documentation$q$, $q$Model files, drawing versions, revision records, issue comments, and supporting files maintained properly$q$, $q$100% updated$q$, $q$BIM Modeler must keep files, versions, and revisions properly recorded.$q$, 10.0::numeric, NULL, $q${"5": "100% model files, drawing versions, revision records and supporting files updated", "4": "90% - 99.99% updated with minor gaps", "3": "75% - 89.99% updated", "2": "50% - 74.99% updated", "1": "< 50% or poor version control evidence"}$q$::jsonb),
  ('BIM_MOD', 5, $q$BIM Productivity & Improvement Contribution$q$, $q$Reusable family / object, modelling efficiency, clash input, template improvement, or workflow improvement contributed$q$, $q$Minimum quarterly contribution$q$, $q$BIM Modeler should help improve modelling efficiency or reusable BIM assets.$q$, 10.0::numeric, NULL, $q${"5": ">= 4 documented productivity / improvement contributions per year", "4": "3 documented productivity / improvement contributions per year", "3": "2 documented productivity / improvement contributions per year", "2": "1 documented productivity / improvement contribution per year", "1": "No improvement contribution evidence"}$q$::jsonb),
  ('BIM_MOD', 6, $q$Commission$q$, $q$Contribution to awarded / eligible commissionable projects based on company commission policy$q$, $q$Minimum 3x employee basic salary$q$, $q$BIM Modeler contributes to awarded projects that qualify for commission.$q$, 5.0::numeric, NULL, $q${"5": ">= 3.00x basic salary achieved", "4": "2.00x - 2.99x basic salary achieved", "3": "1.00x - 1.99x basic salary achieved", "2": "0.50x - 0.99x basic salary achieved", "1": "< 0.50x or no commissionable contribution"}$q$::jsonb),
  ('BIM_MOD', 7, $q$Collaboration & Task Responsiveness$q$, $q$Responds to review comments, coordination requests, drawing changes, and internal task instruction within agreed timeline$q$, $q$>=95% response within agreed timeline$q$, $q$BIM Modeler must respond to comments, changes, and instructions on time.$q$, 3.0::numeric, NULL, $q${"5": ">= 95% response within agreed timeline", "4": "85% - 94.99% response within agreed timeline", "3": "70% - 84.99% response within agreed timeline", "2": "50% - 69.99% response within agreed timeline", "1": "< 50% or poor task responsiveness"}$q$::jsonb),
  ('BIM_MOD', 8, $q$Certification & Competency Development$q$, $q$Achieve relevant BIM, Revit, AutoCAD, Navisworks, modelling, or approved technical competency milestone$q$, $q$Minimum 1 certification / competency milestone per year$q$, $q$BIM Modeler must improve BIM tool and modelling skills.$q$, 2.0::numeric, NULL, $q${"5": "Certification or approved competency milestone achieved", "4": "Training completed / exam attempted with strong progress", "3": "Partial progress recorded", "2": "Limited progress recorded", "1": "No progress evidence Recommended Governance Note KPI rating shall be assessed using a 5-to-1 scale. Rating 5 represents full achievement or exceeding target, while Rating 1 represents non-achievement or insufficient evidence. Assessment shall be based on measurable records such as WO tracker, proposal register, tender outcome, BoM review record, compliance matrix, BIM register, OI register, commission record, certification tracker, meeting minutes, and management reporting evidence."}$q$::jsonb)
) AS v(rc, ln, name, meas, target, expl, w, am, bands)
JOIN ROLE r ON r.rolecode = v.rc
JOIN KPI_TEMPLATE t ON t.roleid = r.id
JOIN KPI_CYCLE c ON c.id = t.cycleid AND c.cyclecode = '2026-H1';

INSERT INTO KPI_ITEM (CycleId, ItemNo, Section, Name, Description, Weight, ScaleMax, InputMode, Bands)
SELECT c.id, v.no, v.sec, v.name, v.descr, v.w, v.sm, v.mode, v.bands
FROM (VALUES
  (1, 'Value', $q$Job Knowledge & Skills$q$, $q$Understanding of tasks, technical knowledge, ability to apply skills$q$, 15.0::numeric, 10, 'Rating', $q${"1-2": "Lacks understanding of job duties; unable to apply required skills without constant supervision.", "3-4": "Limited job knowledge; requires frequent guidance and support.", "5-6": "Understands core responsibilities; performs routine tasks independently.", "7-8": "Strong job knowledge; applies skills effectively with minimal supervision.", "9-10": "Expert-level knowledge; solves complex issues and mentors others."}$q$::jsonb),
  (2, 'Value', $q$Quality of Work$q$, $q$Accuracy, attention to detail, consistency in performance$q$, 10.0::numeric, 10, 'Rating', $q${"1-2": "Frequent errors; poor attention to detail.", "3-4": "Inconsistent accuracy; requires rework.", "5-6": "Generally accurate; it meets basic quality standards.", "7-8": "Consistently accurate; maintains high quality standards.", "9-10": "Exceptional quality; consistently exceeds expectations."}$q$::jsonb),
  (3, 'Value', $q$Productivity & Efficiency$q$, $q$Ability to meet deadlines, handling workload effectively, work orders$q$, 10.0::numeric, 10, 'Rating', $q${"1-2": "Unable to meet deadlines; poor workload management.", "3-4": "Often misses deadlines; requires close supervision.", "5-6": "Meets deadlines for routine tasks; manages workload adequately.", "7-8": "Consistently meets deadlines; handles workload efficiently.", "9-10": "Exceeds productivity targets; highly efficient and reliable."}$q$::jsonb),
  (4, 'Value', $q$Attendance & Punctuality$q$, $q$Regularity, adherence to working hours, promptness$q$, 10.0::numeric, 10, 'Rating', $q${"1-2": "Frequent absenteeism or lateness.", "3-4": "Irregular attendance; often late.", "5-6": "Generally punctual; occasional absence or lateness.", "7-8": "Regular attendance; punctual and dependable.", "9-10": "Perfect or near-perfect attendance and punctuality."}$q$::jsonb),
  (5, 'Value', $q$Initiative & Ownership$q$, $q$Proactiveness, accountability, problem-solving, willingness to take responsibility$q$, 5.0::numeric, 10, 'Rating', $q${"1-2": "Rarely shows initiative; avoids responsibility and requires constant supervision.", "3-4": "Limited initiative; responds only when directed and shows minimal ownership of tasks.", "5-6": "Demonstrates initiative when required; accepts responsibility for assigned tasks and resolves routine issues.", "7-8": "Proactively identifies issues and opportunities; takes ownership of tasks and contributes to problem-solving with minimal supervision.", "9-10": "Consistently demonstrates strong initiative and ownership; independently drives improvements, takes responsibility beyond job scope, and resolves complex issues with positive impact."}$q$::jsonb),
  (6, 'Value', $q$Teamwork & Collaboration$q$, $q$Internal, Cross-Department & Communication Effectiveness$q$, 5.0::numeric, 10, 'Rating', $q${"1-2": "Poor teamwork; unwilling or unable to work effectively with team members or other departments, negatively impacting outcomes.", "3-4": "Limited collaboration; communication gaps or reluctance to engage with team or other departments.", "5-6": "Demonstrates adequate teamwork; able to work with other departments when required and meets collaboration expectations.", "7-8": "Works well with own team and other departments; communicates clearly, cooperatively, and professionally.", "9-10": "Excellent collaborator; proactively engages and coordinates with multiple departments, strengthens teamwork, and contributes positively to delivery outcomes."}$q$::jsonb),
  (7, 'Value', $q$Achievements & Contributions$q$, $q$Key accomplishments, process improvements, additional responsibilities undertaken, project involvement, milestone achievement$q$, 5.0::numeric, 10, 'Rating', $q${"0": "No achievement or contribution demonstrated during the evaluation period.", "1-2": "Minimal or no measurable achievements; contributions below expectations.", "3-4": "Limited contributions; meets basic job expectations with minimal added value.", "5-6": "Achieves assigned targets and responsibilities; contributes effectively within job scope.", "7-8": "Demonstrates notable achievements, measurable improvements, or successful completion of additional responsibilities or project milestones; may participate in awards or recognition programmes.", "9-10": "Outstanding contributions with significant impact on projects, business outcomes, or milestones; demonstrates leadership, innovation, or excellence recognised through special awards or formal recognition."}$q$::jsonb),
  (8, 'Value', $q$Employee Certifications$q$, $q$Points awarded based on relevance of certifications to individual’s role, applicable for certifications $q$, 10.0::numeric, 10, 'Certificates', $q${}$q$::jsonb),
  (9, 'Value', $q$Compliance, Ethics & Professional Conduct$q$, $q$Adherence to company policies, ethical standards, professional behaviour, and regulatory requirements$q$, 10.0::numeric, 10, 'Rating', $q${"1-2": "Frequently breaches company policies or ethical standards; displays unprofessional conduct.", "3-4": "Occasional non-compliance or conduct issues; requires reminders or corrective action.", "5-6": "Complies with policies and ethical standards; maintains acceptable professional conduct.", "7-8": "Consistently adheres to policies and ethical standards; demonstrates integrity and professionalism.", "9-10": "Exemplary conduct; acts as a role model for compliance and ethics, promotes ethical behaviour, and proactively supports compliance culture."}$q$::jsonb),
  (10, 'Value', $q$Adaptability & Change Readiness$q$, $q$Ability to adapt to change, new systems, policies, or priorities$q$, 5.0::numeric, 5, 'Rating', $q${"0": "Resists change; unwilling to adapt to new processes, systems, or requirements.", "1": "Shows reluctance toward change; adapts only after repeated guidance.", "2": "Accepts change when required; adjusts with support or supervision.", "3-4": "Adapts well to change; demonstrates flexibility and maintains performance during transitions.", "5": "Champions change; proactively supports new initiatives and helps others adapt effectively."}$q$::jsonb),
  (11, 'Value', $q$Understanding & Application of SMART$q$, $q$Application of Specific, Measurable, Achievable, Relevant, and Time-bound principles in daily work$q$, 5.0::numeric, 5, 'Rating', $q${"0": "Does not apply SMART principles; tasks are unclear and poorly managed.", "1": "Limited understanding; rarely applies SMART in daily work.", "2": "Basic understanding; applies SMART with guidance.", "3-4": "Applies SMART principles effectively in most tasks; demonstrates structured planning and execution.", "5": "Consistently applies SMART; sets clear, measurable goals and delivers outcomes efficiently."}$q$::jsonb),
  (12, 'Value', $q$Understanding & Application of ISO Practices$q$, $q$Adherence to ISO standards, SOPs, and quality management practices$q$, 5.0::numeric, 5, 'Rating', $q${"0": "Does not follow ISO practices; frequent non-compliance.", "1": "Limited understanding; requires constant reminders.", "2": "Basic compliance; follows procedures with supervision.", "3-4": "Consistently follows ISO practices and maintains proper documentation.", "5": "Fully compliant; promotes best practices and supports quality improvement initiatives."}$q$::jsonb),
  (13, 'Value', $q$Understanding & Application of Entrepreneurial Behaviour$q$, $q$Ownership mindset, initiative, and business-oriented thinking$q$, 5.0::numeric, 5, 'Rating', $q${"0": "No ownership; passive in work responsibilities.", "1": "Limited initiative; depends heavily on instructions.", "2": "Shows basic ownership; completes assigned tasks.", "3-4": "Demonstrates initiative and contributes ideas to improve work or efficiency.", "5": "Strong entrepreneurial mindset; proactively drives value, improvements, and business outcomes."}$q$::jsonb),
  (14, 'Bonus', $q$Contribution in Company Programmes & Engagement Programmes$q$, $q$Committee, Contribution to and participation in company events, engagement programmes, team-building activities, and corporate initiatives$q$, 5.0::numeric, 5, 'Rating', $q${"0": "Does not participate / contribute to in company events or engagement programmes", "1": "Rarely participate / contributes; minimal participation and engagement.", "2": "Takes part when required; limited contribution.", "3-4": "Actively takes part and contributes in most company events or engagement activities.", "5": "Highly engaged; makes significant contributions, takes initiative, or plays an active role in organising or supporting company events and engagement programmes."}$q$::jsonb),
  (15, 'Bonus', $q$Positive Attitude & Professional Conduct$q$, $q$Demonstrates positive mindset, supportive behaviour, and contributes to a healthy and respectful work environment$q$, 5.0::numeric, 5, 'Rating', $q${"0": "Frequently displays negative attitude; impacts team morale and work environment.", "1": "Occasionally positive but inconsistent; may affect teamwork or communication.", "2": "Maintains a positive attitude in general; professional and cooperative when required.", "3-4": "Consistently demonstrates a positive attitude; supportive, respectful, and encourages good teamwork.", "5": "Role model of positive attitude; actively spreads positivity, willingly helps others, and consistently uplifts team morale and workplace culture."}$q$::jsonb),
  (16, 'Bonus', $q$Knowledge Sharing & Mentoring$q$, $q$Sharing knowledge, supporting colleagues, mentoring juniors$q$, 5.0::numeric, 5, 'Rating', $q${"0": "Does not share knowledge or support colleagues.", "1": "Rarely assists others; limited knowledge sharing.", "2": "Provides assistance or shares knowledge when requested.", "3-4": "Actively shares knowledge, supports team members, and contributes to collaborative learning.", "5": "Regularly mentors others; proactively builds team capability and supports long-term knowledge development."}$q$::jsonb),
  (17, 'Bonus', $q$Innovation (Improving Business Delivery)$q$, $q$Ideas or improvements that enhance efficiency, productivity, or service delivery$q$, 5.0::numeric, 5, 'Rating', $q${"0": "No innovation or improvement initiatives.", "1": "Rare ideas with no measurable impact.", "2": "Minor suggestions; limited improvement.", "3-4": "Implements useful improvements that enhance efficiency or processes.", "5": "Delivers impactful innovation with measurable business benefits."}$q$::jsonb)
) AS v(no, sec, name, descr, w, sm, mode, bands)
CROSS JOIN KPI_CYCLE c WHERE c.cyclecode = '2026-H1';

INSERT INTO KPI_OUTCOME_BAND (CycleId, MinScore, Outcome)
SELECT c.id, v.m, v.o
FROM (VALUES
  (0::numeric, $q$Below 70% - Performance Improvement Plan (PIP)$q$),
  (70::numeric, $q$Passed, eligible for increment without performance bonus (if applicable)$q$),
  (80::numeric, $q$Eligible for increment and performance bonus (if applicable)$q$),
  (88::numeric, $q$Eligible for increment, performance bonus (if applicable) and promotion recommendation$q$),
  (92::numeric, $q$Eligible for increment, performance bonus (if applicable), promotion recommendation and best employee nomination$q$)
) AS v(m, o)
CROSS JOIN KPI_CYCLE c WHERE c.cyclecode = '2026-H1';
